import {DOMAIN_LIST, QUESTION_DOMAIN_CLASS, parseQuestions, firstByRegion, scoreRows, dash} from "./assets/helpers.js"
dsv = require("d3-dsv@3")
scores = FileAttachment("data/scores.csv").csv({typed: true})
inclusion = FileAttachment("data/inclusion.csv").csv({typed: true})
responses = firstByRegion(await FileAttachment("data/responses.csv").csv(), "Region")
questions = parseQuestions(dsv.csvParseRows(await FileAttachment("data/questions.csv").text()))
regions = [...new Set(inclusion.filter(r =&gt; r.include === "Yes").map(r =&gt; r.region))].sort()
initialRegion = decodeURIComponent(location.hash.slice(1))



























































viewof region = Inputs.select(["", ...regions], {
  label: "Region",
  value: regions.includes(initialRegion) ? initialRegion : ""
})








regionScores = {
  if (!region) return html``;
  const row = scores.find(r =&gt; r.region === region);
  if (!row) return html`&lt;p style="text-align:center"&gt;No scores available for this region.&lt;/p&gt;`;
  const rows = scoreRows(row);
  return html`&lt;div id="region-scores"&gt;&lt;table class="table"&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;Score&lt;/th&gt;&lt;th&gt;Rank&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${rows.map(r =&gt; html`&lt;tr class=${r.key === "all_domain" ? "overall" : ""} style=${"color:" + r.color}&gt;
      &lt;td&gt;${r.label}&lt;/td&gt;&lt;td&gt;${r.score}&lt;/td&gt;&lt;td&gt;${r.rank}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;
  &lt;/table&gt;&lt;/div&gt;`;
}







regionResponses = {
  if (!region) return html``;
  const row = responses.find(r =&gt; r.Region === region);
  if (!row) return html``;
  return html`&lt;div class="responses"&gt;${questions.map(q =&gt; html`&lt;div class=${QUESTION_DOMAIN_CLASS[q.domain] || ""}&gt;
    &lt;strong class="question"&gt;${q.question}&lt;/strong&gt;
    &lt;p class="scale"&gt;(Scale: ${q.scale})&lt;/p&gt;
    &lt;p class="response"&gt;${row[q.id] ? row[q.id] : "\u2014"}&lt;/p&gt;
  &lt;/div&gt;`)}&lt;/div&gt;`;
}







regionCharacteristics = {
  if (!region) return html``;
  const row = inclusion.find(r =&gt; r.region === region);
  if (!row) return html``;
  return html`&lt;div class="characteristics"&gt;
    &lt;strong&gt;Respondent organization characteristics&lt;/strong&gt;
    &lt;div&gt;Region: ${dash(row.region_size)}&lt;/div&gt;
    &lt;div&gt;Number of members: ${dash(row.members)}&lt;/div&gt;
    &lt;div&gt;Number of members with Down syndrome or with a relative with Down syndrome: ${dash(row.related_to_ds)}&lt;/div&gt;
  &lt;/div&gt;`;
}

Plotly = require("plotly.js-dist-min@2.35.2")
import {DOMAIN_LIST, buildMapTraces, mapLayout} from "./assets/helpers.js"
scores = FileAttachment("data/scores.csv").csv({typed: true})
inclusion = FileAttachment("data/inclusion.csv").csv({typed: true})































viewof domain = Inputs.select(new Map(DOMAIN_LIST), {label: "Ranking Category:", value: "all_domain"})







viewof showExcluded = Inputs.toggle({label: "Show excluded regions?", value: false})








mapDiv = {
  const div = html`&lt;div style="width:100%;height:680px"&gt;&lt;/div&gt;`;
  yield div;
  const traces = buildMapTraces(scores, inclusion, domain, showExcluded);
  await Plotly.newPlot(div, traces, mapLayout(domain), {responsive: true, displaylogo: false});
  div.on("plotly_click", ev =&gt; {
    const p = ev.points[0];
    if (p.curveNumber &gt; 1) return;               // excluded regions have no data page
    const row = scores.find(r =&gt; r.iso === p.location);
    if (row) window.location.href = `region-data.html#${encodeURIComponent(row.region)}`;
  });
}







